/* Plucked-string bass models adapted from Norwegian Beats STRB / strBass.
   No recordings, slap excitation, pitch bends or automatic portamento. */
(function(root){'use strict';const base=root.KroghBass,cache=new WeakMap(),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const models={upright:{name:'Kontrabass · plukket modell',soft:.82,loss:.9935,body:[[110,.9,4],[240,.5,5]],len:2.2,pick:0},finger:{name:'Fingerbass · tydelig anslag',soft:.55,loss:.9965,body:[[180,.35,3]],len:2.6,pick:.22},round:{name:'Rund fingerbass · varm modell',soft:.72,loss:.996,body:[[130,.5,3],[270,.24,4]],len:2.7,pick:.12}};
function buffers(c,id){let bank=cache.get(c);if(!bank){bank=new Map();cache.set(c,bank);}if(bank.has(id))return bank.get(id);const P=models[id],sr=44100,zones=[];let seed=1337;const R=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
for(const midi of [28,33,38,43,48]){const f=440*2**((midi-69)/12),N=Math.round(sr/f-.5),n=Math.round(sr*P.len),y=new Float32Array(n),line=new Float32Array(N);let lp=0;for(let i=0;i<N;i++){lp+=(1-P.soft)*(R()*2-1-lp);line[i]=lp+(i<N*.1?(R()-.5)*.14:0);}let prev=0;for(let i=0;i<n;i++){const j=i%N,x=line[j];line[j]=P.loss*(x+prev)*.5;prev=x;y[i]=x;}if(P.pick){const d=Math.round(N*P.pick);for(let i=n-1;i>=d;i--)y[i]-=.7*y[i-d];}const a=Float32Array.from(y,x=>x*.6);for(const [fc,g,q]of P.body){let x1=0,x2=0,y1=0,y2=0;const w=2*Math.PI*fc/sr,al=Math.sin(w)/(2*q),b0=al/(1+al),b2=-b0,a1=-2*Math.cos(w)/(1+al),a2=(1-al)/(1+al);for(let i=0;i<n;i++){const z=b0*y[i]+b2*x2-a1*y1-a2*y2;x2=x1;x1=y[i];y2=y1;y1=z;a[i]+=z*g;}}let peak=0;for(const x of a)peak=Math.max(peak,Math.abs(x));for(let i=0;i<n;i++)a[i]=a[i]/Math.max(.001,peak)*.8*Math.min(1,(n-i)/(sr*.05));const b=c.createBuffer(1,n,sr);b.copyToChannel(a,0);zones.push({midi,buffer:b});}bank.set(id,zones);return zones;}
function patch(id){return{eng:'physical',name:models[id.slice(5)].name,cut:id==='body:finger'?.67:.57,res:.03,env:.13,dec:.26,amp:.23,drive:.12,atk:.002,rel:.09,glide:0,sour:0,sub:0,g:1};}
function create(c,dest=c.destination,{preset='body:finger'}={}){let id=preset.slice(5),sn=patch(preset),zones=buffers(c,id),active=new Set(),disposed=false,last=null;const out=c.createGain();out.gain.value=.6;out.connect(dest);const stopAll=(time=c.currentTime)=>{for(const v of active){try{v.g.gain.cancelScheduledValues(time);v.g.gain.setTargetAtTime(0,time,.005);v.s.stop(time+.03);}catch{}}};return{
ready:async()=>true,getPatch:()=>({...sn}),set:values=>Object.assign(sn,values),setHost:()=>{},
select(next){if(!models[next.slice(5)])throw Error('Velg en plukket bassmodell.');stopAll();id=next.slice(5);sn=patch(next);zones=buffers(c,id);return{...sn};},
play({midi=36,time=c.currentTime+.01,duration=.25,velocity=100,accent=false}={}){if(disposed)throw Error('Bass engine disposed');const z=zones.reduce((a,b)=>Math.abs(b.midi-midi)<Math.abs(a.midi-midi)?b:a),s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain(),sh=c.createWaveShaper();s.buffer=z.buffer;s.playbackRate.value=2**((midi-z.midi)/12);f.type='lowpass';const baseCut=80*2**((sn.cut??.6)*7.8);f.frequency.setValueAtTime(Math.min(c.sampleRate*.44,baseCut*(1+(sn.env||0)*2)),time);f.frequency.setTargetAtTime(Math.min(c.sampleRate*.44,baseCut),time+.005,.03+(sn.dec||.2)*.2);f.Q.value=.5+(sn.res||0)*5;const cv=new Float32Array(512),drive=1+(sn.drive||0)*5;for(let i=0;i<cv.length;i++){const x=i/(cv.length-1)*2-1;cv[i]=Math.tanh(x*drive)/Math.tanh(drive);}sh.curve=cv;sh.oversample='2x';s.connect(f);f.connect(sh);sh.connect(g);g.connect(out);const end=time+Math.max(.03,duration),release=.018+(sn.rel||0)*.22,peak=clamp(velocity/127,0,1)*(accent?1.12:1);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(peak,time+Math.max(.001,sn.atk||.002));g.gain.setValueAtTime(peak,end);g.gain.setTargetAtTime(0,end,release);if(last){try{last.g.gain.cancelScheduledValues(time);last.g.gain.setTargetAtTime(0,time,.007);}catch{}}const item={s,g,f,sh};last=item;active.add(item);s.onended=()=>{active.delete(item);for(const n of [s,f,sh,g])n.disconnect();};s.start(time);s.stop(end+release*7+.03);},
noteOff:stopAll,dispose(){if(disposed)return;stopAll();for(const x of active){try{x.s.stop();}catch{}for(const n of [x.s,x.f,x.sh,x.g])n.disconnect();}active.clear();out.disconnect();disposed=true;}
};}
const catalog=()=>[...base.catalog().filter(p=>!/slap/i.test(p.name)),...Object.entries(models).map(([id,p])=>({id:'body:'+id,name:p.name,category:'plucked',group:'Plukket bass · modeller',engine:'physical'}))];
root.KroghBass={...base,catalog,patch:(id,...args)=>id.startsWith('body:')?patch(id):base.patch(id,...args),create:(c,dest,opts={})=>opts.preset?.startsWith('body:')?create(c,dest,opts):base.create(c,dest,opts)};
})(typeof globalThis!=='undefined'?globalThis:this);
